import { cookies } from 'next/headers'
import { redirect } from 'next/navigation'

const CONTACT_ERROR_COOKIE = 'contact_form_error'
const CONTACT_SUCCESS_COOKIE = 'contact_form_success'

async function submitContact(formData: FormData) {
  'use server'

  const name = String(formData.get('name') ?? '').trim()
  const email = String(formData.get('email') ?? '').trim()
  const message = String(formData.get('message') ?? '').trim()

  if (!name || !email || !message) {
    const cookieStore = await cookies()
    cookieStore.set(CONTACT_ERROR_COOKIE, 'Please provide your name, email, and message.', {
      maxAge: 60,
      path: '/',
      httpOnly: true,
      sameSite: 'lax',
    })
    redirect('/')
  }

  console.log('Contact message:', { name, email, message })

  const cookieStore = await cookies()
  cookieStore.set(CONTACT_SUCCESS_COOKIE, '1', {
    maxAge: 60,
    path: '/',
    httpOnly: true,
    sameSite: 'lax',
  })
  redirect('/')
}

export default async function ContactForm() {
  const cookieStore = await cookies()
  const errorMessage = cookieStore.get(CONTACT_ERROR_COOKIE)?.value
  const success = cookieStore.get(CONTACT_SUCCESS_COOKIE)?.value

  if (errorMessage) {
    cookieStore.delete(CONTACT_ERROR_COOKIE)
  }
  if (success) {
    cookieStore.delete(CONTACT_SUCCESS_COOKIE)
  }

  return (
    <div style={{ marginTop: '2rem' }}>
      <h2>Contact Us</h2>
      {errorMessage ? (
        <p role="alert" style={{ color: '#b00020' }}>
          {errorMessage}
        </p>
      ) : null}
      {success ? (
        <p role="status" style={{ color: '#0d6b2c' }}>
          Thanks — your message was sent.
        </p>
      ) : null}
      <form action={submitContact}>
        <div style={{ marginBottom: '0.75rem' }}>
          <label htmlFor="contact-name" style={{ display: 'block', marginBottom: '0.25rem' }}>
            Name
          </label>
          <input
            id="contact-name"
            name="name"
            type="text"
            autoComplete="name"
            placeholder="Your name"
            required
            style={{ width: '100%', maxWidth: '24rem' }}
          />
        </div>
        <div style={{ marginBottom: '0.75rem' }}>
          <label htmlFor="contact-email" style={{ display: 'block', marginBottom: '0.25rem' }}>
            Email
          </label>
          <input
            id="contact-email"
            name="email"
            type="email"
            autoComplete="email"
            placeholder="you@example.com"
            required
            style={{ width: '100%', maxWidth: '24rem' }}
          />
        </div>
        <div style={{ marginBottom: '0.75rem' }}>
          <label htmlFor="contact-message" style={{ display: 'block', marginBottom: '0.25rem' }}>
            Message
          </label>
          <textarea
            id="contact-message"
            name="message"
            placeholder="Your message"
            required
            rows={5}
            style={{ width: '100%', maxWidth: '24rem' }}
          />
        </div>
        <button type="submit">Send message</button>
      </form>
    </div>
  )
}

